  "Entered: {0}, {1}, {2}, {3}, {4}, {5}, {6}, {7}{8}Left: {9}, {10}, {11}, {12}, {13}, {14}, {15}, {16}": "Hinzugekommen: {0}, {1}, {2}, {3}, {4}, {5}, {6}, {7}{8}Ausgeschieden: {9}, {10}, {11}, {12}, {13}, {14}, {15}, {16}",
  "Entered: {0}, {1}, {2}, {3}, {4}, {5}{6}Left: {7}, {8}, {9}, {10}, {11}, {12}": "Hinzugekommen: {0}, {1}, {2}, {3}, {4}, {5}{6}Ausgeschieden: {7}, {8}, {9}, {10}, {11}, {12}",
